let rawBody = $json.body ?? $json;
let body = rawBody;

// n8n sometimes gives webhook body as a parsed object, and sometimes as a JSON string.
// Paperless/httpx automation is currently sending it as a JSON string.
if (typeof body === 'string') {
  const trimmed = body.trim();
  try {
    body = JSON.parse(trimmed);
  } catch (e) {
    // Fallback for non-JSON text bodies: keep the raw string so URL regex below can still work.
    body = { raw_body: trimmed };
  }
}

let id = body.document_id || body.doc_id || body.id || body.document;
if (typeof id === 'object' && id !== null) id = id.id || id.pk;

const urlCandidates = [
  body.doc_url,
  body.url,
  body.document_url,
  body.raw_body,
  typeof rawBody === 'string' ? rawBody : '',
];

for (const candidate of urlCandidates) {
  if (id) break;
  const match = String(candidate || '').match(/\/documents\/(\d+)(?:\/|$|\?)/i);
  if (match) id = match[1];
}

id = Number(id);
if (!Number.isInteger(id) || id <= 0) {
  throw new Error(`Could not determine Paperless document id from webhook body. Parsed body=${JSON.stringify(body)} Raw body=${JSON.stringify(rawBody)}`);
}

return [{ json: { doc_id: id, original_webhook_body: body, original_raw_body: rawBody } }];

const meta = $('Fetch Metadata').item.json;
const tagsResponse = $('Fetch Tags').item.json;
const allTags = Array.isArray(tagsResponse) ? tagsResponse : (tagsResponse.results || []);

const tagBySlugOrName = (wanted) => allTags.find(t =>
  String(t.slug || '').toLowerCase() === wanted.toLowerCase() ||
  String(t.name || '').toLowerCase() === wanted.toLowerCase()
);

// Required: ocr-processing — set by Paperless auto-tag rule before the webhook fires.
// Required: ocr-done — set on the replacement doc at upload time so Paperless's
//           re-consume of the new doc short-circuits at the Guard.
// Optional: ocr-inflight — set by the poller before firing the webhook to prevent
//           duplicate fires while OCR is running. Stripped from the replacement doc.
const done = tagBySlugOrName('ocr-done') || tagBySlugOrName('llm-ocr-complete');
const processing = tagBySlugOrName('ocr-processing') || tagBySlugOrName('llm-ocr-processing');
const inflight = tagBySlugOrName('ocr-inflight');
const legacyNeeds = tagBySlugOrName('needs-llm-ocr'); // tolerated for old test docs; not required anymore.

if (!done) throw new Error('Could not find Paperless tag named/sluggified ocr-done. Create it in Paperless or change this node.');
if (!processing) throw new Error('Could not find Paperless tag named/sluggified ocr-processing. Create it in Paperless and have the Paperless workflow assign it before calling n8n.');

const removeIds = new Set([Number(processing.id)]);
if (legacyNeeds) removeIds.add(Number(legacyNeeds.id));
if (inflight) removeIds.add(Number(inflight.id));

const newTags = (meta.tags || [])
  .map(t => Number(typeof t === 'object' ? t.id : t))
  .filter(id => Number.isInteger(id) && !removeIds.has(id));

if (!newTags.includes(Number(done.id))) newTags.push(Number(done.id));

// Paperless document PATCH expects custom_fields as a LIST of { field, value } items.
const customFields = [];
for (const cf of (meta.custom_fields || [])) {
  const fieldId = cf.field ?? cf.id ?? cf.custom_field;
  if (fieldId === undefined || fieldId === null) continue;
  customFields.push({
    field: Number(fieldId),
    value: cf.value ?? null,
  });
}

const permissions = {};
if (meta.permissions) permissions.set_permissions = meta.permissions;

return [{
  json: {
    old_doc_id: $('Extract Doc ID').item.json.doc_id,
    title: meta.title || `Document ${$('Extract Doc ID').item.json.doc_id}`,
    created: meta.created,
    correspondent: meta.correspondent,
    document_type: meta.document_type,
    storage_path: meta.storage_path,
    // Do NOT patch archive_serial_number before deleting the old document.
    // ASN is unique in Paperless, so setting the same ASN on the new doc while
    // the old doc still exists can trigger another 400. It is restored after deletion.
    archive_serial_number: meta.archive_serial_number,
    owner: meta.owner,
    tags: newTags,
    custom_fields: customFields,
    done_tag_id: Number(done.id),
    processing_tag_id: Number(processing.id),
    inflight_tag_id: inflight ? Number(inflight.id) : null,
    legacy_needs_tag_id: legacyNeeds ? Number(legacyNeeds.id) : null,
    ...permissions,
    missing_pages: [],
  },
  binary: $input.item.binary,
}];

const taskId = String($json.data || '').trim().replace(/^"|"$/g, '');

if (!taskId) {
  throw new Error(`Could not parse Paperless upload task id from response: ${JSON.stringify($json)}`);
}

return [{
  json: {
    upload_task_id: taskId,
    old_doc_id: $('Build Replacement Metadata').item.json.old_doc_id,
  }
}];

const uploadTaskId = $('Parse Upload Task ID').item.json.upload_task_id;
if (!uploadTaskId) {
  throw new Error(`Missing upload_task_id from Parse Upload Task ID. Got: ${JSON.stringify($('Parse Upload Task ID').item.json)}`);
}

const resp = $json;
const tasks = Array.isArray(resp) ? resp : (resp.results || []);
const task = tasks[0] || resp;
const status = String(task.status || task.state || '').toUpperCase();

let result = task.result;
if (typeof result === 'string') {
  try { result = JSON.parse(result); } catch (e) {}
}

let docId = task.document_id || task.related_document || task.document || task.related_document_id;
if (!docId && result && typeof result === 'object') {
  docId = result.document_id || result.document || result.id || result.pk;
}
if (!docId && typeof task.result === 'string') {
  const patterns = [
    /document[_ ]?id['" :]+(\d+)/i,
    /created document (\d+)/i,
    /document (\d+)/i,
    /id['" :]+(\d+)/i,
  ];
  for (const p of patterns) {
    const match = task.result.match(p);
    if (match) { docId = Number(match[1]); break; }
  }
}

if (!docId || ['FAILURE','FAILED','REVOKED'].includes(status)) {
  throw new Error(`Paperless has not confirmed the replacement document yet. Wait longer and inspect /api/tasks/?task_id=${uploadTaskId}. Status=${status || 'unknown'} Result=${JSON.stringify(task.result)}`);
}

return [{ json: { new_doc_id: Number(docId), old_doc_id: $('Build Replacement Metadata').item.json.old_doc_id } }];

