={{ (() => {
  const m = $('Build Replacement Metadata').item.json;
  const body = {
    title: m.title,
    created: m.created,
    correspondent: m.correspondent,
    document_type: m.document_type,
    storage_path: m.storage_path,
    owner: m.owner,
    tags: m.tags,
    custom_fields: Array.isArray(m.custom_fields) ? m.custom_fields : [],
  };
  // Do not send undefined values, and do not send archive_serial_number here.
  // The old document still exists at this point, so ASN can violate uniqueness.
  return Object.fromEntries(Object.entries(body).filter(([key, value]) => value !== undefined));
})() }}

parameters.jsCode:
const asn = $('Build Replacement Metadata').item.json.archive_serial_number;
if (asn === undefined || asn === null || asn === '') {
  return [];
}
return [{
  json: {
    new_doc_id: $('Validate New Document').item.json.new_doc_id,
    archive_serial_number: asn,
  }
}];

const meta = $('Fetch Metadata').item.json;
const tagsResponse = $json;
const allTags = Array.isArray(tagsResponse) ? tagsResponse : (tagsResponse.results || []);

const findTag = (wanted) => allTags.find(t =>
  String(t.slug || '').toLowerCase() === wanted.toLowerCase() ||
  String(t.name || '').toLowerCase() === wanted.toLowerCase()
);

const done = findTag('ocr-done') || findTag('llm-ocr-complete');
const processing = findTag('ocr-processing') || findTag('llm-ocr-processing');

if (!done) {
  throw new Error('Could not find Paperless tag named/sluggified ocr-done. Create it in Paperless or change this node.');
}
if (!processing) {
  throw new Error('Could not find Paperless tag named/sluggified ocr-processing. Create it and have the Paperless workflow assign it before calling this webhook.');
}

const currentTagIds = new Set((meta.tags || []).map(t => Number(typeof t === 'object' ? t.id : t)));
const hasDone = currentTagIds.has(Number(done.id));
const hasProcessing = currentTagIds.has(Number(processing.id));

// Option A: OCR every new document.
// Paperless should assign ocr-processing before calling this webhook.
// Replacement documents are uploaded with ocr-done immediately, so they stop here if Paperless fires again.
// Returning [] intentionally stops the workflow without an error.
if (hasDone || !hasProcessing) {
  return [];
}

return [{
  json: {
    doc_id: $('Extract Doc ID').item.json.doc_id,
    trigger_ok: true,
    done_tag_id: done.id,
    processing_tag_id: processing.id,
    reason: 'Document has ocr-processing and does not have ocr-done.'
  }
}];

// Call OCR Service was configured with fullResponse:true, so $json contains
// headers / statusCode / body and the binary still lives at $input.item.binary.
// When the OCR service decides the PDF already has a text layer it returns the
// input unchanged plus X-OCR-Skipped: true; uploading that to Paperless would
// be rejected as a duplicate, so we have to branch.
const rawHeaders = $json.headers || ($json.response && $json.response.headers) || {};
const headers = Object.fromEntries(
  Object.entries(rawHeaders).map(([k, v]) => [String(k).toLowerCase(), v]),
);
const skippedHeader = String(headers['x-ocr-skipped'] || '').toLowerCase();
const ocrSkipped = skippedHeader === 'true';

return [{
  json: {
    ocr_skipped: ocrSkipped,
    ocr_status_code: $json.statusCode ?? null,
    ocr_headers: headers,
    old_doc_id: $('Extract Doc ID').item.json.doc_id,
  },
  binary: $input.item.binary,
}];

// Skipped path: we never produced a new PDF. Re-tag the OLD document so it
// leaves the ocr-processing / ocr-inflight set and gains ocr-done. No upload,
// no delete, no duplicate-hash failure.
const meta = $('Fetch Metadata').item.json;
const guard = $('Guard OCR Trigger Tags').item.json;
const tagsResponse = $('Fetch Tags').item.json;
const allTags = Array.isArray(tagsResponse) ? tagsResponse : (tagsResponse.results || []);

const findTag = (wanted) => allTags.find(t =>
  String(t.slug || '').toLowerCase() === wanted.toLowerCase() ||
  String(t.name || '').toLowerCase() === wanted.toLowerCase()
);

const inflight = findTag('ocr-inflight');
const legacy = findTag('needs-llm-ocr');

const removeIds = new Set([Number(guard.processing_tag_id)]);
if (inflight) removeIds.add(Number(inflight.id));
if (legacy) removeIds.add(Number(legacy.id));

const newTags = (meta.tags || [])
  .map(t => Number(typeof t === 'object' ? t.id : t))
  .filter(id => Number.isInteger(id) && !removeIds.has(id));

const doneId = Number(guard.done_tag_id);
if (!newTags.includes(doneId)) newTags.push(doneId);

return [{
  json: {
    old_doc_id: $('Extract Doc ID').item.json.doc_id,
    tags: newTags,
    reason: 'OCR service reported X-OCR-Skipped: true (existing text layer).',
  }
}];
